import {spawn} from "node:child_process";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";
import {mkdtempSync, rmSync} from "node:fs";
import {tmpdir} from "node:os";
import puppeteer from "puppeteer";

const HERE = dirname(fileURLToPath(import.meta.url));
const CHROME = process.env.CHROME || "/usr/bin/google-chrome";

let passed = 0, failed = 0;
function check(name, cond, extra) {
  if (cond) { passed++; console.log("PASS", name); }
  else { failed++; console.log("FAIL", name, extra === undefined ? "" : JSON.stringify(extra)); }
}

const dataDir = mkdtempSync(join(tmpdir(), "cb-import-"));
const server = spawn("python3", [join(HERE, "app.py"), "serve", "--port", "0", "--data-dir", dataDir], {stdio: ["ignore", "pipe", "inherit"]});
const base = await new Promise((resolve, reject) => {
  server.stdout.on("data", d => {
    const m = String(d).match(/http:\/\/[^\s]+/);
    if (m) resolve(m[0]);
  });
  server.on("exit", () => reject(new Error("server exited")));
});

const browser = await puppeteer.launch({executablePath: CHROME, args: ["--no-sandbox"]});

async function newPageWithImportMock(mock) {
  const page = await browser.newPage();
  await page.setRequestInterception(true);
  page.on("request", req => {
    const url = req.url();
    if (mock && url.includes("/api/clients/import")) {
      req.respond(mock);
    } else if (mock && mock.breakClients && url.includes("/api/clients")) {
      req.respond({status: 500, contentType: "application/json", body: '{"error":"boom"}'});
    } else {
      req.continue();
    }
  });
  await page.goto(base + "/", {waitUntil: "networkidle0"});
  return page;
}

async function submitCsv(page, csvText) {
  // 通过 DataTransfer 注入文件并提交表单
  await page.evaluate(text => {
    const dt = new DataTransfer();
    dt.items.add(new File([text], "test.csv", {type: "text/csv"}));
    const input = document.getElementById("file-input");
    input.files = dt.files;
    document.getElementById("import-form").requestSubmit();
  }, csvText);
  await page.waitForFunction(() => !document.getElementById("submit-btn").disabled, {timeout: 5000});
  return page.evaluate(() => ({
    html: document.getElementById("report").innerHTML,
    text: document.getElementById("report").innerText,
    fileKept: document.getElementById("file-input").files.length === 1,
    btnEnabled: !document.getElementById("submit-btn").disabled,
  }));
}

try {
  // 1. HTTP 500 + 错误说明：不得出现绿色成功或 undefined
  {
    const page = await newPageWithImportMock({status: 500, contentType: "application/json", body: '{"error":"数据库内部错误"}'});
    const r = await submitCsv(page, "name\n甲公司\n");
    check("500 不显示成功横幅", !r.html.includes("banner ok"), r.text);
    check("500 不出现 undefined", !r.text.includes("undefined"), r.text);
    check("500 显示服务说明", r.text.includes("数据库内部错误"), r.text);
    check("500 提示没有可靠结果", r.text.includes("没有取得可靠的导入结果"), r.text);
    check("500 不声称资料未变化", !r.text.includes("保持原样"), r.text);
    check("500 文件保留且按钮恢复", r.fileKept && r.btnEnabled);
    await page.close();
  }
  // 2. 200 但报告缺字段：结果无法确认，不补零
  {
    const page = await newPageWithImportMock({status: 200, contentType: "application/json", body: '{"failures":[]}'});
    const r = await submitCsv(page, "name\n甲公司\n");
    check("缺字段不显示成功", !r.html.includes("banner ok"), r.text);
    check("缺字段提示无法确认", r.text.includes("无法确认"), r.text);
    check("缺字段提示核对列表", r.text.includes("核对客户列表"), r.text);
    await page.close();
  }
  // 3. 200 但明细条数与未导入数量不一致
  {
    const page = await newPageWithImportMock({status: 200, contentType: "application/json",
      body: '{"imported_count":1,"failed_count":2,"failures":[{"row":1,"reason":"x"}]}'});
    const r = await submitCsv(page, "name\n甲公司\n");
    check("明细不符不显示成功", !r.html.includes("banner ok"), r.text);
    check("明细不符提示无法确认", r.text.includes("无法确认"), r.text);
    await page.close();
  }
  // 4. 200 但负数数量 / 非法明细行号
  {
    const page = await newPageWithImportMock({status: 200, contentType: "application/json",
      body: '{"imported_count":-1,"failed_count":0,"failures":[]}'});
    const r = await submitCsv(page, "name\n甲公司\n");
    check("负数数量不显示成功", !r.html.includes("banner ok") && r.text.includes("无法确认"), r.text);
    await page.close();
  }
  // 5. 200 合法报告 + 列表读取失败：保留数量与原因，仅附加提示
  {
    const page = await newPageWithImportMock({status: 200, contentType: "application/json",
      body: '{"imported_count":1,"failed_count":1,"failures":[{"row":2,"reason":"名称为空"}]}',
      breakClients: true});
    const r = await submitCsv(page, "name\n甲公司\n\n");
    check("成功报告显示新增1", r.text.includes("新增 1 条"), r.text);
    check("成功报告显示未导入1", r.text.includes("未导入 1 条"), r.text);
    check("成功报告显示逐条原因", r.text.includes("第 2 条") && r.text.includes("名称为空"), r.text);
    check("列表失败仅附加提示", r.text.includes("列表暂未更新") && r.text.includes("稍后刷新"), r.text);
    check("列表失败不把导入说成失败", !r.text.includes("导入请求失败"), r.text);
    await page.close();
  }
  // 6. 真实 400（缺 name 列）：整份拒绝
  {
    const page = await newPageWithImportMock(null);
    const r = await submitCsv(page, "source\n广告\n");
    check("400 显示整份拒绝", r.text.includes("整份文件已拒绝导入"), r.text);
    check("400 显示具体原因", r.text.includes("缺少名称列"), r.text);
    check("400 说明没有新增", r.text.includes("本次没有新增客户"), r.text);
    await page.close();
  }
  // 7. 真实 200 仅有表头：两项均为零
  {
    const page = await newPageWithImportMock(null);
    const r = await submitCsv(page, "name,source\n");
    check("仅表头显示零新增", r.text.includes("新增 0 条") && r.text.includes("未导入 0 条"), r.text);
    check("仅表头无明细框", !r.html.includes("failures"), r.text);
    await page.close();
  }
  // 8. 真实 200 混合记录：部分新增 + 逐条原因；再导入重复 → 零新增全部未导入
  {
    const page = await newPageWithImportMock(null);
    const r1 = await submitCsv(page, "name,important_date\n混合甲,2024-01-01\n,2024-01-01\n混合乙,2024-13-40\n");
    check("混合显示新增1未导入2", r1.text.includes("新增 1 条") && r1.text.includes("未导入 2 条"), r1.text);
    check("混合显示两条原因", r1.text.includes("第 2 条") && r1.text.includes("第 3 条"), r1.text);
    const r2 = await submitCsv(page, "name\n混合甲\n");
    check("重复导入零新增", r2.text.includes("新增 0 条") && r2.text.includes("未导入 1 条"), r2.text);
    check("重复原因含已有编号", r2.text.includes("重复"), r2.text);
    await page.close();
  }
} finally {
  await browser.close();
  server.kill("SIGTERM");
  rmSync(dataDir, {recursive: true, force: true});
}
console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed ? 1 : 0);

